/**
 * Creates the site Footer element.
 *
 * @param {Object}   args
 * @param {Array}    args.legalLinks   - Array of { label, href } objects for the legal links
 * @param {Array}    args.socialLinks  - Array of { platform, href } objects for social icons
 * @returns {HTMLElement}
 */
export const createFooter = ({
  legalLinks = [
    { label: 'Terms and conditions', href: '#' },
    { label: 'Privacy policy', href: '#' },
    { label: 'Accessibility Statement', href: '#' },
  ],
  socialLinks = [
    { platform: 'X', href: '#' },
    { platform: 'YouTube', href: '#' },
    { platform: 'Facebook', href: '#' },
    { platform: 'TikTok', href: '#' },
    { platform: 'Instagram', href: '#' },
    { platform: 'LinkedIn', href: '#' },
  ],
} = {}) => {
  const footer = document.createElement('footer');
  footer.className = 'mo-footer';

  // ── Top section ───────────────────────────────────────────────
  const top = document.createElement('div');
  top.className = 'mo-footer__top';

  // Logo
  const logo = document.createElement('a');
  logo.className = 'mo-footer__logo';
  logo.href = '#';
  logo.innerHTML = MET_OFFICE_LOGO_SVG;
  top.appendChild(logo);

  // Legal links
  const linksList = document.createElement('ul');
  linksList.className = 'mo-footer__links';

  legalLinks.forEach(({ label, href }) => {
    const li = document.createElement('li');
    const a = document.createElement('a');
    a.className = 'mo-footer__link';
    a.href = href;
    a.textContent = label;
    li.appendChild(a);
    linksList.appendChild(li);
  });

  top.appendChild(linksList);
  footer.appendChild(top);

  // ── Bottom section ────────────────────────────────────────────
  const bottom = document.createElement('div');
  bottom.className = 'mo-footer__bottom';

  socialLinks.forEach(({ platform, href }) => {
    const icon = SOCIAL_ICONS[platform];
    if (!icon) return;

    const a = document.createElement('a');
    a.className = 'mo-footer__social-link';
    a.href = href;
    a.setAttribute('aria-label', icon.label);
    a.innerHTML = icon.svg;
    bottom.appendChild(a);
  });

  footer.appendChild(bottom);

  return footer;
};
